#include "../Source/PluginProcessor.h"
#include <iostream>
#include <stdexcept>
using Buffer=juce::AudioBuffer<float>;
void set(SpaceProcessor& p,const char* id,float v){auto* a=p.state.getParameter(id);a->setValueNotifyingHost(a->convertTo0to1(v));}
double energy(const Buffer& b,int count){double e=0;for(int c=0;c<2;++c)for(int n=0;n<count;++n){double x=b.getSample(c,n);if(!std::isfinite(x))throw std::runtime_error("nonfinite audio");e+=x*x;}return e;}
float peak(const Buffer& b){return std::max(b.getMagnitude(0,0,b.getNumSamples()),b.getMagnitude(1,0,b.getNumSamples()));}
void save(juce::File f,const Buffer& b,double sr){juce::WavAudioFormat format;auto stream=f.createOutputStream();if(!stream)throw std::runtime_error("output unavailable");stream->setPosition(0);stream->truncate();std::unique_ptr<juce::AudioFormatWriter>w(format.createWriterFor(stream.get(),sr,2,24,{},0));if(!w)throw std::runtime_error("writer error");stream.release();if(!w->writeFromAudioSampleBuffer(b,0,b.getNumSamples()))throw std::runtime_error("write failed");}
Buffer render(const Buffer& dry,double sr,int mode){SpaceProcessor p;p.setNonRealtime(true);p.setCurrentProgram(0);if(mode==1)set(p,"spaceOn",0);if(mode==2)set(p,"timeOn",0);if(mode>=3){set(p,"delay",45);set(p,"reverb",50);set(p,"feedback",45);set(p,"size",65);set(p,"focus",mode==3?0:75);}p.prepareToPlay(sr,256);Buffer result(2,dry.getNumSamples()+(int)(sr*4)),block(2,256);result.clear();juce::MidiBuffer midi;for(int offset=0;offset<result.getNumSamples();offset+=256){block.clear();int count=std::min(256,dry.getNumSamples()-offset);if(count>0)for(int c=0;c<2;++c)block.copyFrom(c,0,dry,c,offset,count);p.processBlock(block,midi);int available=std::min(256,result.getNumSamples()-offset);for(int c=0;c<2;++c)result.copyFrom(c,offset,block,c,0,available);}return result;}
int main(int argc,char**argv){swell::Licence::unlockForTesting();try{juce::ScopedJuceInitialiser_GUI init;if(argc!=3)throw std::runtime_error("Usage: SpaceDemo source.wav output-folder");juce::AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<juce::AudioFormatReader>r(formats.createReaderFor(juce::File(argv[1])));if(!r)throw std::runtime_error("source unavailable");int len=(int)std::min(r->lengthInSamples,(juce::int64)(8*r->sampleRate));double sr=r->sampleRate;Buffer dry(2,len);r->read(&dry,0,len,0,true,true);if(r->numChannels==1)dry.copyFrom(1,0,dry,0,0,len);require_unused:;if(peak(dry)<1e-5)throw std::runtime_error("silent source");juce::File out(argv[2]);out.createDirectory();save(out.getChildFile("00-voix-originale.wav"),dry,sr);
juce::String report="Source locale : extrait vocal deja utilise pour Swell Vocal Lift. AcoustiAngel, Freesound #739037, CC0 selon la provenance conservee. https://freesound.org/people/AcoustiAngel/sounds/739037/\nExtrait de l'apercu MP3 HQ, 4 a 12 s de l'original.\nTraitement hors ligne par SpaceProcessor, le meme code compile et lie au VST3/Standalone 0.1.0 (pas un effet de substitution).\nTempo 120 BPM, 1/4 normal. Voix seche 8 s puis pause 0.5 s puis version traitee 8 s + queue 4 s.\nComparaisons RMS egalisees sur les 8 s actives, pas une mesure LUFS. La queue n'entre pas dans l'egalisation.\n";
const char* names[]={"01-Vocal-Clean","02-Delay-seul","03-Reverb-seule","04-Ambiance-Focus-0","05-Ambiance-Focus-75"};
for(int mode=0;mode<5;++mode){auto wet=render(dry,sr,mode);double e=energy(wet,len);if(e<1e-12)throw std::runtime_error("silent render");float gain=(float)std::sqrt(energy(dry,len)/e);wet.applyGain(gain);if(peak(wet)>=.99f)throw std::runtime_error("clipping");save(out.getChildFile(juce::String(names[mode])+"-apres.wav"),wet,sr);int gap=(int)(sr*.5);Buffer ab(2,len+gap+wet.getNumSamples());ab.clear();for(int c=0;c<2;++c){ab.copyFrom(c,0,dry,c,0,len);ab.copyFrom(c,len+gap,wet,c,0,wet.getNumSamples());}save(out.getChildFile(juce::String(names[mode])+"-AVANT-APRES.wav"),ab,sr);report+=juce::String(names[mode])+": compensation "+juce::String(20*std::log10(gain),3)+" dB ; pic "+juce::String(20*std::log10(peak(wet)),3)+" dBFS.\n";}
report+="Vocal Clean : delay 17%, feedback 24%, reverb 22%, size 38%, Focus 65%. Variantes separees : memes reglages avec un effet coupe. Ambiance : delay45%, feedback45%, reverb50%, size65%, Focus0 ou75%.\n";out.getChildFile("SOURCE-ET-METHODE.txt").replaceWithText(report);std::cout<<report;return 0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
